from pathlib import Path
import base64
p=Path(__file__).resolve().parent/'output'
data=base64.b64encode((p/'personalized-rocket.glb').read_bytes()).decode()
(p/'viewer.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campus Explorer — souvenir sample</title><script type="module" src="https://unpkg.com/@google/model-viewer@4.0.0/dist/model-viewer.min.js"></script><style>body{margin:0;background:#edf1f5;color:#142740;font:16px system-ui}header{padding:32px 6vw}h1{margin:8px 0;font-size:34px}p{color:#54677a}model-viewer{width:100%;height:70vh}footer{padding:0 6vw 24px}a{color:#142740}</style><header><small>PERSONALIZED KEEPSAKES / SAMPLE 001</small><h1>Campus Explorer</h1><p>Drag to rotate · Scroll to zoom · Name and base are actual 3D geometry</p></header><model-viewer camera-controls auto-rotate shadow-intensity="1" exposure="1.2" camera-orbit="20deg 75deg auto" alt="Rocket souvenir with navy gold base and HKUST Visitor nameplate" src="data:model/gltf-binary;base64,'''+data+'''"></model-viewer><footer>Source mesh: <a href="https://kenney.nl/assets/space-kit">Kenney Space Kit</a> · CC0 · Customized digital assembly, not yet validated for printing.</footer></html>''')
